import{_ as d,C as i,o as l,c,a6 as o,E as a,j as t,a as n}from"./chunks/framework.CMg4qq8Q.js";const b=JSON.parse('{"title":"HTTP Host Header Attacks","description":"Host routing, password-reset poisoning, cache poisoning, routing SSRF, absolute-URI parsing, and dangling markup.","frontmatter":{"title":"HTTP Host Header Attacks","description":"Host routing, password-reset poisoning, cache poisoning, routing SSRF, absolute-URI parsing, and dangling markup."},"headers":[],"relativePath":"host-header/index.md","filePath":"host-header/index.md"}'),h={name:"host-header/index.md"};function p(u,e,g,m,k,v){const s=i("LabGroup"),r=i("TopicComplete");return l(),c("div",null,[e[0]||(e[0]=o(`<h1 id="http-host-header-attacks-·-the-identity-swap" tabindex="-1">HTTP Host Header Attacks · The Identity Swap <a class="header-anchor" href="#http-host-header-attacks-·-the-identity-swap" aria-label="Permalink to &quot;HTTP Host Header Attacks · The Identity Swap&quot;">​</a></h1><p class="wd-section-lede">The <code>Host</code> header was introduced in HTTP/1.1 to allow multiple websites to share a single IP address (virtual hosting). Because browsers set this header automatically, developers often assume it is authoritative and trustworthy. In reality, the Host header is completely client-controlled. When servers trust it to construct absolute links, make access-control decisions, or route internal requests, attackers can poison caches, steal reset tokens, and breach internal networks.</p><div class="wd-callout"><p><strong>💡 Everyday Analogy: The Sticky Note on Your Forehead.</strong> Imagine walking into a massive office building that houses dozens of different corporate tenants. In the lobby, you tell the front desk security guard: <em>&quot;I have an appointment at Global Bank.&quot;</em> Global Bank welcomes you into their office. While there, you request an official bank verification letter to be mailed to your colleague. But instead of looking up its own corporate headquarters in the telephone directory, Global Bank&#39;s automated mailing machine reads the handwritten sticky note stuck on your forehead: <code>Official Headquarters: evil-attacker.com</code>! The bank prints that address on the letter and mails it out. When your colleague clicks the verification link in the letter, their confidential credentials land straight in the attacker&#39;s hands.</p></div><h2 id="case-file-7-the-anatomy-of-a-host-header-attack" tabindex="-1">Case File #7: The Anatomy of a Host Header Attack <a class="header-anchor" href="#case-file-7-the-anatomy-of-a-host-header-attack" aria-label="Permalink to &quot;Case File #7: The Anatomy of a Host Header Attack&quot;">​</a></h2><p>When web frameworks need to generate an absolute URL (for example, inside an email confirmation or password reset notification), they frequently pull the domain directly from <code>request.headers[&quot;Host&quot;]</code> rather than a hardcoded configuration setting.</p><div class="wd-case"><div class="wd-step wd-step--see"><span class="wd-step__tag">🔎 Step 1 · What You Notice in the Browser</span><p>You visit a website&#39;s &quot;Forgot Password&quot; page and request a reset link for an account. Intercepting the request in an HTTP proxy, you replace <code>Host: example.com</code> with <code>Host: attacker.com</code>. The server replies with a friendly <code>200 OK: Check your email</code>.</p></div><div class="wd-step wd-step--server"><span class="wd-step__tag">⚙️ Step 2 · What the Server Does Behind the Scenes</span><p>The backend application generates a unique, cryptographically random password-reset token. To build the reset link, it evaluates: <code>&quot;https://&quot; + req.headers[&quot;host&quot;] + &quot;/reset?token=&quot; + token</code>. It embeds this link into an email and delivers it to the registered user&#39;s inbox.</p></div><div class="wd-step wd-step--break"><span class="wd-step__tag">💥 Step 3 · Where the Logic Breaks</span><p>The server relied on an untrusted client header to identify its own public domain name. When the legitimate victim opens their email and clicks the reset button, their browser sends the private reset token directly to the attacker&#39;s server, resulting in an instant account takeover.</p></div><div class="wd-step wd-step--fix"><span class="wd-step__tag">🛡️ Step 4 · How Developers Lock It Down</span><p>Define the canonical base URL in server-side configuration settings (e.g. <code>SITE_DOMAIN = &quot;example.com&quot;</code>) and use it exclusively for email links and redirects. Configure reverse proxies to reject any request carrying an unrecognized Host header.</p></div></div><h3 id="visual-comparison-hardcoded-truth-vs-client-assumption" tabindex="-1">Visual Comparison: Hardcoded Truth vs. Client Assumption <a class="header-anchor" href="#visual-comparison-hardcoded-truth-vs-client-assumption" aria-label="Permalink to &quot;Visual Comparison: Hardcoded Truth vs. Client Assumption&quot;">​</a></h3><div class="wd-compare"><div class="wd-compare__card wd-compare__card--expect"><span class="wd-compare__title">💭 What the Developer Expected</span><p>The Host header is set by standard web browsers to point to the current site. It accurately reflects the server&#39;s public identity and can be trusted to generate emails and redirects.</p></div><div class="wd-compare__card wd-compare__card--actual"><span class="wd-compare__title">💥 What Actually Happened</span><p>The client replaced the Host header with an external domain. The server trusted the header and mailed a password-reset link pointing to the attacker&#39;s server, leaking the secret token.</p></div></div><h3 id="spotting-the-spoofed-authority" tabindex="-1">Spotting the Spoofed Authority <a class="header-anchor" href="#spotting-the-spoofed-authority" aria-label="Permalink to &quot;Spotting the Spoofed Authority&quot;">​</a></h3><p>Look at how the modified header rewrites the server&#39;s generated link:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Legitimate API Endpoint</span><span><span class="wd-code-input">Gold</span> = Tampered Host Header</span><span><span class="wd-code-dead">Strikethrough</span> = Resulting Email Reset Link</span></div><span class="wd-code-dev">POST /forgot-password HTTP/1.1<br></span><span class="wd-code-input">Host: attacker.com<br></span><span class="wd-code-dev">Content-Type: application/x-www-form-urlencoded<br><br>username=victim_user<br><br></span><span class="wd-code-dead">Email Generated: https://attacker.com/reset-password?token=secret987xyz</span></div><details class="details custom-block"><summary>🔬 Under the Hood: Absolute-Form URLs vs. Origin-Form Requests</summary><p>An HTTP/1.1 request line can take multiple forms according to RFC 9112:</p><ul><li><strong>Origin-Form:</strong> <code>GET /admin HTTP/1.1</code> (Relies on the <code>Host</code> header to know the destination)</li><li><strong>Absolute-Form:</strong> <code>GET http://example.com/admin HTTP/1.1</code> (Contains the full URL directly in the request line)</li></ul><p>When an attacker sends an absolute-form request containing both a URL host and a conflicting <code>Host</code> header:</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> http://internal-admin.local/ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Host</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public-store.com</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>If a reverse proxy routes based on the absolute URI while the backend server checks the <code>Host</code> header (or vice versa), the attacker can bypass front-end IP restrictions or access forbidden intranet admin consoles!</p></details><hr><h2 id="the-5-stage-life-of-a-password-reset-poisoning-attack" tabindex="-1">The 5-Stage Life of a Password-Reset Poisoning Attack <a class="header-anchor" href="#the-5-stage-life-of-a-password-reset-poisoning-attack" aria-label="Permalink to &quot;The 5-Stage Life of a Password-Reset Poisoning Attack&quot;">​</a></h2><p>Follow the flow of a poisoned Host header from initial trigger to account takeover:</p><div class="wd-flow"><div class="wd-flow__node wd-flow__node--danger"><strong>1. Attacker Trigger</strong> Attacker submits a password reset for the victim, injecting <code>Host: attacker.com</code>. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>2. Insecure Link Assembly</strong> Server creates a secret reset token and glues the untrusted Host header into the link. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>3. Email Delivery</strong> Server sends an official email to the victim&#39;s genuine inbox containing the poisoned link. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>4. Victim Clicks</strong> Victim believes the email is legitimate and clicks the button, sending the token to <code>attacker.com</code>. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--safe"><strong>5. Account Takeover</strong> Attacker reads the token from their server logs and resets the victim&#39;s password! </div></div><hr><h2 id="where-the-host-header-is-used" tabindex="-1">Where the Host Header is Used <a class="header-anchor" href="#where-the-host-header-is-used" aria-label="Permalink to &quot;Where the Host Header is Used&quot;">​</a></h2><p>Applications regularly reuse the Host header in multiple critical areas:</p><table tabindex="0"><thead><tr><th>Operational Use</th><th>Typical Attack Surface</th><th>Impact</th></tr></thead><tbody><tr><td>Building Absolute URLs in Emails</td><td>Password Reset Poisoning</td><td>Complete Account Takeover</td></tr><tr><td>Routing to Virtual Hosts</td><td>Admin Interface Access Bypass</td><td>Unauthorized Admin Panel Access</td></tr><tr><td>Cache Key Construction</td><td>Web Cache Poisoning</td><td>Mass Stored XSS / Redirection</td></tr><tr><td>Internal Service Discovery</td><td>Routing-Based SSRF</td><td>Access to Cloud Metadata &amp; Intranet</td></tr><tr><td>Access-Control Checks</td><td><code>Host: localhost</code> Header Spoofing</td><td>Bypass Perimeter IP Allow-Lists</td></tr></tbody></table>`,20)),a(s,{ids:"host-header-lab-host-header-basic-password-reset-poisoning, host-header-lab-host-header-authentication-bypass"}),e[1]||(e[1]=t("hr",null,null,-1)),e[2]||(e[2]=t("h2",{id:"password-reset-poisoning-via-dangling-markup",tabindex:"-1"},[n("Password Reset Poisoning via Dangling Markup "),t("a",{class:"header-anchor",href:"#password-reset-poisoning-via-dangling-markup","aria-label":'Permalink to "Password Reset Poisoning via Dangling Markup"'},"​")],-1)),e[3]||(e[3]=t("p",null,[n("In some hardened systems, the application validates the Host header against a whitelist, preventing arbitrary domains. However, if the server permits port numbers or specific characters, an attacker can inject "),t("strong",null,"dangling markup"),n(" into the Host header (e.g., "),t("code",null,`Host: example.com:'<a href="http://attacker.com/?`),n(").")],-1)),e[4]||(e[4]=t("p",null,"When the server embeds this malformed string into the email HTML without proper attribute quoting, the browser consumes all following characters—including the genuine password reset token—and appends them to the attacker's URL parameter!",-1)),a(s,{ids:"host-header-lab-host-header-password-reset-poisoning-via-dangling-markup"}),e[5]||(e[5]=o('<hr><h2 id="web-cache-poisoning-via-ambiguous-requests" tabindex="-1">Web Cache Poisoning via Ambiguous Requests <a class="header-anchor" href="#web-cache-poisoning-via-ambiguous-requests" aria-label="Permalink to &quot;Web Cache Poisoning via Ambiguous Requests&quot;">​</a></h2><p>When a front-end cache and a backend web server handle ambiguous or malformed Host headers differently, an attacker can poison the cache for legitimate users.</p><p>Techniques for injecting ambiguous host headers include:</p><ul><li><strong>Duplicate Host Headers:</strong> Sending two <code>Host</code> headers in a single request. If the cache keys on the first header (<code>example.com</code>) but the backend application renders based on the second (<code>attacker.com</code>), the cached page will serve attacker content to everyone.</li><li><strong>Line Wrapping (RFC 7230 Obsolete):</strong> Prepending a space or tab before a second Host header line.</li><li><strong>X-Forwarded-Host Spoofing:</strong> Supplying <code>Host: legitimate.com</code> with <code>X-Forwarded-Host: attacker.com</code>. If the backend prioritizes the forward header, the cache stores the poisoned response.</li></ul>',5)),a(s,{ids:"host-header-lab-host-header-web-cache-poisoning-via-ambiguous-requests"}),e[6]||(e[6]=o(`<hr><h2 id="routing-based-ssrf" tabindex="-1">Routing-Based SSRF <a class="header-anchor" href="#routing-based-ssrf" aria-label="Permalink to &quot;Routing-Based SSRF&quot;">​</a></h2><p>Many modern cloud architectures use reverse proxies that route incoming requests directly based on the destination found in the <code>Host</code> header.</p><p>If an attacker transmits an HTTP request targeting an internal IP address or internal service name in the <code>Host</code> header:</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /admin </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Host</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 192.168.0.1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>The reverse proxy forwards the request into the private corporate network, converting an ordinary HTTP request into Server-Side Request Forgery (SSRF) without needing any URL input parameter.</p>`,6)),a(s,{ids:"host-header-lab-host-header-routing-based-ssrf, host-header-lab-host-header-ssrf-via-flawed-request-parsing"}),e[7]||(e[7]=o('<hr><h2 id="connection-state-attacks" tabindex="-1">Connection-State Attacks <a class="header-anchor" href="#connection-state-attacks" aria-label="Permalink to &quot;Connection-State Attacks&quot;">​</a></h2><p>Some enterprise load balancers validate the <code>Host</code> header only during the very first request on a newly opened TCP keep-alive connection.</p><p>In a <strong>connection-state attack</strong>, an attacker opens a persistent TCP connection and sends a completely valid, authorized request first. Then, down the exact same open socket, they immediately transmit a second request with a forbidden <code>Host</code> header (such as <code>Host: internal-admin.corp</code>). The front-end reuses the verified connection state without re-evaluating the host, granting access to restricted endpoints.</p>',4)),a(s,{ids:"host-header-lab-host-header-host-validation-bypass-via-connection-state-attack"}),e[8]||(e[8]=o('<details class="details custom-block"><summary>⚙️ Engine Variations: How Web Servers Handle the Host Header</summary><ul><li><strong>Nginx:</strong> The <code>$host</code> variable checks the request line host, then the <code>Host</code> header, and finally falls back to the default <code>server_name</code>. Using <code>$http_host</code> returns the exact raw client-provided header (including custom ports).</li><li><strong>Apache HTTP Server:</strong> Resolves virtual hosts using <code>ServerName</code> and <code>ServerAlias</code>. The <code>UseCanonicalName</code> directive determines whether Apache uses the configured name or client header when generating self-referencing URLs.</li><li><strong>Node.js:</strong> <code>req.headers.host</code> exposes the unvalidated client string. Modern frameworks advise using <code>URL</code> parsing with an explicit base origin.</li><li><strong>Java Spring / Servlets:</strong> <code>HttpServletRequest.getServerName()</code> can return the client&#39;s <code>Host</code> header unless explicit connector configuration forces canonical names.</li><li><strong>Cloud Load Balancers:</strong> Frequently overwrite or append <code>X-Forwarded-Host</code> and <code>X-Forwarded-Proto</code>. Relying on these headers without verifying edge trust invites spoofing.</li></ul></details><div class="wd-callout wd-callout--warn"><p><strong>🛡️ Defensive Blueprint: How to Lock Down Host Header Handling</strong></p><ol><li><strong>Use Hardcoded Canonical Domain Configurations:</strong> Never generate email links, password reset URLs, or payment callbacks using <code>req.headers[&quot;host&quot;]</code>. Read the base domain strictly from a server environment variable.</li><li><strong>Strict Virtual Host Allow-Lists:</strong> Configure Nginx, Apache, or cloud load balancers to reject any incoming request whose Host header does not match a strict list of allowed domain names (return <code>404 Not Found</code> or <code>400 Bad Request</code>).</li><li><strong>Configure a Dummy Default Host:</strong> Ensure the default virtual host for unmatched requests serves an empty error page rather than routing to sensitive internal services.</li><li><strong>Protect Forwarded Headers:</strong> Ensure backend applications only trust <code>X-Forwarded-Host</code> when it originates from a verified, authenticated internal reverse proxy.</li></ol></div>',2)),a(r,{"topic-id":"http-host-header-attacks",label:"Mark Host header attacks complete"})])}const f=d(h,[["render",p]]);export{b as __pageData,f as default};
